<body>

<div class="yd-monitor-wrapper" id="yd-main-app">

  <!-- 隐藏的数据源 -->
  <div id="yd-raw-sys-time">$1</div>
  <div id="yd-raw-comp-data">$2</div>

  <div class="yd-header-bar">
    <div class="yd-sys-time-container" id="yd-parsed-time">
      <!-- JS 将在此处生成时间块 -->
    </div>
  </div>

  <div class="yd-tab-nav" id="yd-tab-nav-container">
    <!-- JS 将在此处生成 Tab 按钮 -->
  </div>

  <div class="yd-content-area" id="yd-tab-content-container">
    <!-- JS 将在此处生成面板内容 -->
  </div>

</div>

<script>
  document.addEventListener('DOMContentLoaded', function() {
    // 1. 解析系统时间
    const rawTimeStr = document.getElementById('yd-raw-sys-time').textContent.trim();
    const timeContainer = document.getElementById('yd-parsed-time');

    if (rawTimeStr) {
      // 假设格式: 2025/10/24-周五-19:30-微雨
      const timeParts = rawTimeStr.split('-');
      timeParts.forEach(part => {
        if(part.trim()) {
          const block = document.createElement('div');
          block.className = 'yd-time-block';
          block.textContent = part.trim();
          timeContainer.appendChild(block);
        }
      });
    }

    // 2. 解析学伴数据
    const rawDataStr = document.getElementById('yd-raw-comp-data').textContent.trim();
    const navContainer = document.getElementById('yd-tab-nav-container');
    const contentContainer = document.getElementById('yd-tab-content-container');


    // 检查是否为空或暂无
    if (!rawDataStr || rawDataStr === '暂无' || rawDataStr.includes('暂无学伴')) {
      navContainer.innerHTML = '<button class="yd-tab-btn active">SYSTEM</button>';
      contentContainer.innerHTML = '<div class="yd-tab-pane active"><div class="yd-empty-state">NO COMPANION DATA DETECTED</div></div>';
      return;
    }

    // 按 --- 分割学伴
    const companions = rawDataStr.split('---').map(s => s.trim()).filter(s => s.length > 0);

  console.log(companions)

    companions.forEach((compText, index) => {
      // 提取辅助函数
      const extractVal = (key) => {
        const regex = new RegExp(key + ':\\s*([^\\n]*)');
        const match = compText.match(regex);
        return match ? match[1].trim() : 'N/A';
      };

      const name = extractVal('Name');
      const age = extractVal('Age');
      const rank = extractVal('Rank');
      const dims = extractVal('Dims');
      const outfit = extractVal('Outfit');
      const body = extractVal('Body');

      // 创建 Tab 按钮
      const btn = document.createElement('button');
      btn.className = 'yd-tab-btn' + (index === 0 ? ' active' : '');
      btn.textContent = name || ('Target ' + (index+1));
      btn.dataset.target = 'yd-pane-' + index;

      btn.addEventListener('click', function() {
        // 移除所有 active
        document.querySelectorAll('.yd-tab-btn').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.yd-tab-pane').forEach(p => p.classList.remove('active'));
        // 添加当前 active
        this.classList.add('active');
        document.getElementById(this.dataset.target).classList.add('active');
      });
      navContainer.appendChild(btn);

      // 判定评级样式
      const isSRank = rank.includes('S');
      const rankHtml = `<span class="yd-rank-display ${isSRank ? 'yd-rank-s' : 'yd-rank-normal'}">${rank}</span>`;

      // 创建内容面板
      const pane = document.createElement('div');
      pane.className = 'yd-tab-pane' + (index === 0 ? ' active' : '');
      pane.id = 'yd-pane-' + index;

      pane.innerHTML = `
        <div class="yd-data-grid">
          <div class="yd-data-row" style="border-left-color: var(--yd-neon-purple);">
            <div class="yd-label">NAME</div>
            <div class="yd-value" style="font-size: 1.2rem; font-weight: bold; color: #fff;">${name}</div>
          </div>
          <div class="yd-data-row">
            <div class="yd-label">AGE</div>
            <div class="yd-value">${age}</div>
          </div>
          <div class="yd-data-row">
            <div class="yd-label">RANK</div>
            <div class="yd-value">${rankHtml}</div>
          </div>
          <div class="yd-data-row">
            <div class="yd-label">DIMS</div>
            <div class="yd-value yd-highlight-dims">${dims}</div>
          </div>
          <div class="yd-data-row">
            <div class="yd-label">OUTFIT</div>
            <div class="yd-value">${outfit}</div>
          </div>
          <div class="yd-data-row">
            <div class="yd-label">BODY</div>
            <div class="yd-value yd-highlight-body">${body}</div>
          </div>
        </div>
      `;
      contentContainer.appendChild(pane);
    });
  });

</script>
</body>
